// FILE: src/data/mythFactCards.ts
//
// GENERATED FROM src/data/myth_fact_cards.csv. DO NOT EDIT BY HAND, AND DO NOT
// REWORD A CARD.
//
// The sixty cards were written and checked for accuracy away from this code,
// and the CSV is the copy of record. This file exists because the site imports
// typed data rather than parsing a CSV in the browser, and because a typo in a
// condition should be a compile error rather than a card that never shows.
//
// `npm run verify` reads the CSV again and compares it with this file, cell by
// cell, so the two cannot drift: a card edited here and not there, or reworded
// on the way through, fails the run. Regenerate rather than edit.
//
// Every column of the CSV is kept, including `showWhen` as its own English
// sentence. That sentence is what the reader is owed when they ask why they
// were shown this card, and `src/data/mythFactMatch.ts` carries the predicate
// that decides it — the two are deliberately separate, so the words a reader
// sees can never be quietly edited to match what the code happens to do.

/** Which companies a card is about. The CSV's own three values. */
export type MythFactAppliesTo = 'Non-banks only' | 'All companies' | 'Banks only';

/** The subject, as the CSV groups them. */
export type MythFactTopic = 'Working capital' | 'Cash flow' | 'Debt' | 'Profitability' | 'Valuation' | 'Growth' | 'Dividends' | 'Accounting' | 'Banks/financials';

export interface MythFactCard {
  /** The CSV's own ID. Stable: it is how a card is referred to anywhere else. */
  id: number;
  /** The belief, stated plainly, as something a reader might hold. */
  myth: string;
  /** What is actually the case. */
  fact: string;
  /** The mechanism behind the fact. Shown behind the ⓘ, never in the open. */
  why: string;
  /** The condition on the company's filed figures, in English. */
  showWhen: string;
  topic: MythFactTopic;
  appliesTo: MythFactAppliesTo;
}

